import{_ as t,o as a,c as i,a3 as s}from"./chunks/framework.B_jDsKE8.js";const y=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/architecture.md","filePath":"explanation/architecture.md"}'),n={name:"explanation/architecture.md"};function o(r,e,d,c,l,p){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><h2 id="the-idea" tabindex="-1">The idea <a class="header-anchor" href="#the-idea" aria-label="Permalink to &quot;The idea&quot;">​</a></h2><p>One long-lived <strong>age identity</strong> per person per machine — the master key every age-encrypted store on the box decrypts with. tardigrada owns that key&#39;s <em>lifecycle</em>: bootstrap, inspect, move. It never touches ciphertext, vaults, refs, or envs — those belong to the consumers (cuora, tamias sealed packs, rage).</p><p>Named for the tardigrade: the animal survives anything by entering cryptobiosis — a dormant state it persists through until conditions return. The identity sleeps in the platform session keyring (or a <code>0600</code> keyfile) and wakes whenever a store needs it; it persists across tools, machines, and years.</p><h2 id="components" tabindex="-1">Components <a class="header-anchor" href="#components" aria-label="Permalink to &quot;Components&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tardigrada (CLI)</span></span>
<span class="line"><span>   │  clap parse → backend select → dispatch → i32</span></span>
<span class="line"><span>   │  (crates/tardigrada, lib + thin bin)</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>IdentitySource impls — consumed from cuora, git-pinned cuora-v1.0.2</span></span>
<span class="line"><span>   ├─ KeyringIdentity   system keyring entry tardigrada/age-identity</span></span>
<span class="line"><span>   │                    (secret-service / Keychain / Credential Manager)</span></span>
<span class="line"><span>   └─ FileIdentity      identity.txt keyfile, mode 0600, fsync</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>session keyring  or  identity.txt at the resolved path</span></span></code></pre></div><p>Backend selection mirrors cuora: <code>TARDIGRADA_IDENTITY_BACKEND</code> = <code>keyring</code> (default, fail closed) | <code>auto</code> (keyring → keyfile fallback) | <code>file</code> (keyfile only). An explicit <code>--identity-file</code>/<code>TARDIGRADA_IDENTITY_FILE</code> pin always means file and never probes the store.</p><p>Single crate, no driver: the command ships as a tamias <code>type: files</code> pack with a <code>payload:</code> bin (<code>libraries/tardigrada</code>) — a real binary staged by <code>scripts/pack.sh</code>, deployed onto PATH by <code>tamias install</code>. Same shape as <code>tarsi</code>&#39;s pack; no <code>bins[]</code> shim, no <code>tamias-driver-*</code> crate.</p><h2 id="ports-inherited-not-reinvented" tabindex="-1">Ports (inherited, not reinvented) <a class="header-anchor" href="#ports-inherited-not-reinvented" aria-label="Permalink to &quot;Ports (inherited, not reinvented)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Piece</th><th>Source</th></tr></thead><tbody><tr><td><code>IdentitySource</code> port + <code>ensure()</code></td><td><code>cuora-identity</code> (git <code>cuora-v1.0.2</code>)</td></tr><tr><td><code>FileIdentity</code> keyfile impl</td><td><code>cuora-identity-file</code> (git <code>cuora-v1.0.2</code>)</td></tr><tr><td><code>KeyringIdentity</code> session-store impl</td><td><code>cuora-identity-keyring</code> (git <code>cuora-v1.0.2</code>)</td></tr><tr><td><code>x25519::Identity</code></td><td><code>age</code> (default-features off)</td></tr></tbody></table><p><code>tardigrada</code> resolves one <code>IdentitySource</code> per run — a <code>KeyringIdentity</code> or a <code>FileIdentity</code> at the resolved path. The impls are path-agnostic, so tardigrada&#39;s <code>~/.config/tardigrada/</code> location, cuora&#39;s, and the shared <code>tardigrada/age-identity</code> keyring entry are the same code — and the same identity.</p><h2 id="where-it-sits" tabindex="-1">Where it sits <a class="header-anchor" href="#where-it-sits" aria-label="Permalink to &quot;Where it sits&quot;">​</a></h2><p>Delivery → memory → process → interface: tardigrada is <strong>process</strong> infrastructure — a lifecycle tool other tools&#39; identities flow through. cuora (secrets broker) consumes the identity for vault decryption; tamias (distribution) ships the binary; myco (work memory) tracks the ledger; tarsi (release plane) cuts the tags.</p><h2 id="neighbors" tabindex="-1">Neighbors <a class="header-anchor" href="#neighbors" aria-label="Permalink to &quot;Neighbors&quot;">​</a></h2><p>See <a href="./boundaries.html">Boundaries</a> for the owns / doesn&#39;t-own split and the per-neighbor relationship table; <a href="./decisions.html">Decisions</a> for the why behind each of those lines.</p>`,15)])])}const u=t(n,[["render",o]]);export{y as __pageData,u as default};
